insert into public.shop_categories (slug, name, description, image, sort) values ('couples', 'Matching Couple Cardigans', 'His & hers sets knitted from the same yarn lot.', 'https://images.unsplash.com/photo-1523523262500-ec13396518c6?auto=format&fit=crop&w=1400&q=80', 7) on conflict (slug) do nothing;

with p as (
  insert into public.shop_products (slug, name, subtitle, description, price_cents, compare_at_cents, audience, badge, sizes, materials, care, details, processing_time, featured, sort)
  values ('marshmallow-cloud-cardigan', 'Marshmallow Cloud Cardigan', 'Our signature oversized knit', 'The cardigan that started it all. Knitted slowly by hand in a squishy, cloud-soft yarn, the Marshmallow Cloud has dropped shoulders, deep ribbed cuffs and an easy oversized shape you can wear open or wrapped. It feels like a hug from someone who loves you.', 14800, null, 'women', 'bestseller', array['XS', 'S', 'M', 'L', 'XL', 'XXL']::text[], '70% merino wool, 30% baby alpaca. Horn-effect buttons.', 'Hand wash cold with wool wash, or dry clean. Lay flat to dry and reshape while damp. Store folded, never hung.', array['Hand-knitted from start to finish — about 30 hours per cardigan', 'Oversized, relaxed fit with dropped shoulders', 'Two deep patch pockets', 'Five buttons, wear open or closed']::text[], null, true, 0)
  on conflict (slug) do nothing returning id
), cats as (
  insert into public.shop_product_categories (product_id, category_slug) select p.id, c from p, unnest(array['women', 'oversized', 'chunky']::text[]) c returning 1
), cols as (
  insert into public.shop_product_colors (product_id, name, hex, sort) select p.id, x.name, x.hex, x.ord - 1 from p,
    (values ('Cream', '#F3EADB', 1), ('Blush', '#EFC9C3', 2), ('Sky', '#CFE0EC', 3)) as x(name, hex, ord) returning 1
), imgs as (
  insert into public.shop_product_images (product_id, url, alt, sort) select p.id, x.url, x.alt, x.ord - 1 from p,
    (values ('https://images.unsplash.com/photo-1588271968087-4c51abe05afc?auto=format&fit=crop&w=1400&q=80', 'Model wearing a soft cream knit cardigan', 1), ('https://images.unsplash.com/photo-1773747310674-b42a55d72003?auto=format&fit=crop&w=1400&q=80', 'Cream fuzzy knit hanging on a hanger', 2), ('https://images.unsplash.com/photo-1643016087636-69ebfe9c6450?auto=format&fit=crop&w=1400&q=80', 'Close-up of the cloud-soft knit texture', 3)) as x(url, alt, ord) returning 1
)
